package com.bookstore.cart.service;
import com.bookstore.book.repository.BookRepository; import com.bookstore.cart.dto.CartItemRequest; import com.bookstore.cart.entity.*; import com.bookstore.cart.repository.*; import com.bookstore.user.entity.User; import com.bookstore.user.repository.UserRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CartService { private final CartRepository carts; private final CartItemRepository items; private final BookRepository books; private final UserRepository users; public CartService(CartRepository c,CartItemRepository i,BookRepository b,UserRepository u){carts=c;items=i;books=b;users=u;} public Cart get(String username){return carts.findByUserUsername(username).orElseGet(()->carts.save(new Cart(users.findByUsername(username).orElseThrow())));} public Cart add(String username,CartItemRequest r){var c=get(username);var b=books.findById(r.bookId()).orElseThrow();var item=c.getItems().stream().filter(x->x.getBook().getId().equals(b.getId())).findFirst().orElse(null);if(item==null){item=new CartItem(c,b,r.quantity());c.getItems().add(item);}else item.setQuantity(item.getQuantity()+r.quantity());return carts.save(c);} public void remove(Long id){items.deleteById(id);} }
